}

{
  "fol": "∀ar ((NaturalOrLegalPerson(ar) ∧ ∃u (Union(u) ∧ (LocatedInUnion(ar, u) ∨ EstablishedInUnion(ar, u))) ∧ ∃wm (WrittenMandate(wm) ∧ ReceivedMandate(ar, wm) ∧ AcceptedMandate(ar, wm) ∧ ∃prov (Provider(prov) ∧ MandateFrom(wm, prov) ∧ (∃s (AISystem(s) ∧ ProvidedBy(s, prov)) ∨ ∃m (GeneralPurposeAIModel(m) ∧ ProvidedBy(m, prov))) ∧ ∃op ∃r (ObligationsAndProcedures(op) ∧ Regulation(r) ∧ EstablishedBy(op, r) ∧ PerformsOnBehalf(ar, op, prov) ∧ CarriesOutOnBehalf(ar, op, prov))))) ⇒ AuthorisedRepresentative(ar))"
