}

{
  "fol": "∀p ((FirstMakingAvailable(p) ∧ ∃um (UnionMarket(um) ∧ (∃s (AISystem(s) ∧ MakesAvailableOn(p, s, um)) ∨ ∃m (GPAIModel(m) ∧ MakesAvailableOn(p, m, um))))) ⇒ PlacedOnMarket(p))"
