{
  "fol": "∀p ((∃s (AISystem(s) ∧ SupplyForFirstUse(p, s) ∧ (∃d (Deployer(d) ∧ SuppliedDirectlyTo(p, d)) ∨ SuppliedForOwnUse(p, s)) ∧ InTheUnion(p) ∧ ∃i (IntendedPurpose(i) ∧ ForIntendedPurpose(p, i)))) ⇒ PutIntoService(p))"
